  `similar_meanings` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `similar_spellings` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `translation` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `word_type` enum('CUSTOM','SYLLABUS') COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
